vec3 col3 = vec3(-1, 1.0 , 2.0 );
vec3 col4 = vec3( 1.0 ,-1, 2.0 );
vec2 d = (vec2(1.0)/uTexSize)*1.25;
vec3 dx = ( GetPixel(uv + vec2( 1.0 , 0.0 )*d) - GetPixel(uv-vec2( 1.0 , 0.0 )*d).xy );
vec3 dy = ( GetPixel(uv + vec2( 0.0 , 1.0 )*d) - GetPixel(uv-vec2( 0.0 , 1.0 )*d).xy );
float c = 8;
float dd = 1;
vec3 light1 = dd - pow(length(uv-vec2(lum(dx),lum(dy))*c-pos1),.2);
vec3 light2 = dd - pow(length(uv-vec2(lum(dx),lum(dy))*c-pos2),.2);
vec3 light3 = dd - pow(length(uv-vec2(lum(dx),lum(dy))*c-pos3),.2);
vec3 light4 = dd - pow(length(uv-vec2(lum(dx),lum(dy))*c-pos4),.2);
ret = mix(GetPixel(uv),max(max(light1*col1,light2*col2),max(light3*col3,light4*col4)),0.5);
}
  fragColor = vec4(ret, 1.0);
}

